69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
78	    private static final int MAX_OWNERS_PER_CITY = 50;
79	
80	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
81	    private static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
84	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final AddressNormalizer addressNormalizer;
97	
98	    private final EmailNormalizer emailNormalizer;
99	
100	    private final IdentityKeyResolver identityKeyResolver;
101	
102	    private final HouseholdResolver householdResolver;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 AddressNormalizer addressNormalizer,
110	                                 EmailNormalizer emailNormalizer,
111	                                 IdentityKeyResolver identityKeyResolver,
112	                                 HouseholdResolver householdResolver) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.telephoneNormalizer = telephoneNormalizer;
118	        this.addressNormalizer = addressNormalizer;
119	        this.emailNormalizer = emailNormalizer;
120	        this.identityKeyResolver = identityKeyResolver;
121	        this.householdResolver = householdResolver;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        owners.forEach(this::populateHouseholdMemberCount);
137	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
138	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        populateHouseholdMemberCount(owner);
149	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
154	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
155	     * by the mapper alone.
156	     *
157	     * @param owner the owner to map
158	     * @return the owner DTO carrying its identity key
159	     */
160	    private OwnerDto toOwnerDto(Owner owner) {
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
163	        return ownerDto;
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
170	        normalizeAndValidate(ownerFieldsDto);
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        populateDerivedFields(owner, ownerFieldsDto);
174	        requireUniqueIdentity(owner);
175	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
176	        flagPossibleDuplicate(owner, ownerFieldsDto);
177	        this.clinicService.saveOwner(owner);
178	        populateHouseholdMemberCount(owner);
179	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
180	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
181	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(),
182	                owner.getHouseholdMemberCount(), owner.getRegistrationDate()));
183	        OwnerDto ownerDto = toOwnerDto(owner);
184	        headers.setLocation(UriComponentsBuilder.newInstance()
185	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
186	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    /**
190	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
191	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
192	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
193	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
194	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
195	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
196	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
197	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
198	     *
199	     * @param owner          the newly mapped owner about to be saved
200	     * @param ownerFieldsDto the incoming owner payload
201	     */
202	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
203	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
204	        owner.setNamesakeCount(countNamesakes(owner));
205	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
206	        assignHouseholdId(owner);
207	    }
208	
209	    /**
210	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
211	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
212	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
213	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
214	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
215	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
216	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
217	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
218	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
219	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
220	     * assigned (see {@link #requireUniqueIdentity}).
221	     *
222	     * @param ownerFieldsDto the incoming owner payload, mutated in place
223	     * @throws MissingOwnerFieldsException if any required field is missing or blank
224	     */
225	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
226	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
227	        validateRequiredFields(ownerFieldsDto);
228	        validatePostcode(ownerFieldsDto);
229	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
230	        ownerFieldsDto.setTelephone(telephone);
231	        requireCityHasCapacity(ownerFieldsDto.getCity());
232	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
233	        ownerFieldsDto.setRegistrationDate(registrationDate);
234	        requireDailyLimitNotReached(registrationDate);
235	        normalizeEmail(ownerFieldsDto);
236	    }
237	
238	    /**
239	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
240	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
241	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
242	     * place so the caller can map and save it directly.
243	     *
244	     * @param ownerFieldsDto the incoming owner payload, mutated in place
245	     */
246	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
247	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
248	    }
249	
250	    /**
251	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
252	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
253	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
254	     * later than the current server date is rejected.
255	     *
256	     * @param ownerFieldsDto the incoming owner payload
257	     * @return the effective registration date rolled forward onto a business day
258	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
259	     */
260	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
261	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
262	        if (effective == null) {
263	            effective = LocalDate.now();
264	        }
265	        else if (effective.isAfter(LocalDate.now())) {
266	            throw new FutureRegistrationDateException(
267	                "the registration date must not be later than the current server date");
268	        }
269	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
270	            effective = effective.plusDays(1);
271	        }
272	        return effective;
273	    }
274	
275	    /**
276	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
277	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
278	     * further owner may be created for that day.
279	     *
280	     * @param registrationDate the adjusted business-day registration date of the owner being created
281	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
282	     */
283	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
284	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
285	            throw new DailyOwnerLimitExceededException(
286	                "the maximum number of owners for today has already been reached");
287	        }
288	    }
289	
290	    /**
291	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
292	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
293	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
294	     * warning threshold) so both express the same per-day count in one place.
295	     *
296	     * @param registrationDate the adjusted business-day registration date to count owners for
297	     * @return the number of existing owners registered on that day
298	     */
299	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
300	        return this.clinicService.findAllOwners().stream()
301	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
302	            .count();
303	    }
304	
305	    /**
306	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
307	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
308	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
309	     * reflects only owners that predate it.
310	     *
311	     * @param registrationDate the adjusted business-day registration date of the owner being created
312	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
313	     */
314	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
315	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
316	    }
317	
318	    /**
319	     * Counts how many existing owners already share the given owner's first and last name, compared
320	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
321	     * create; it is zero when the owner's name is unique.
322	     *
323	     * @param owner the newly mapped owner about to be saved
324	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
325	     */
326	    private int countNamesakes(Owner owner) {
327	        String firstName = owner.getFirstName();
328	        String lastName = owner.getLastName();
329	        return (int) this.clinicService.findAllOwners().stream()
330	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
331	                && lastName.equalsIgnoreCase(existing.getLastName()))
332	            .count();
333	    }
334	
335	    /**
336	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
337	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
338	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
339	     *
340	     * @param ownerFieldsDto the owner payload to validate
341	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
342	     */
343	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
344	        List<String> missingFields = new ArrayList<>();
345	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
346	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
347	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
348	        requireText(missingFields, "city", ownerFieldsDto.getCity());
349	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
350	        if (!missingFields.isEmpty()) {
351	            throw new MissingOwnerFieldsException(missingFields);
352	        }
353	    }
354	
355	    private void requireText(List<String> missingFields, String fieldName, String value) {
356	        if (value == null || value.isBlank()) {
357	            missingFields.add(fieldName);
358	        }
359	    }
360	
361	    /**
362	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
363	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
364	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
365	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
366	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
367	     *
368	     * @param ownerFieldsDto the incoming owner payload
369	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
370	     */
371	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
372	        String postcode = ownerFieldsDto.getPostcode();
373	        if (postcode == null) {
374	            return;
375	        }
376	        Region region = Region.forCity(ownerFieldsDto.getCity());
377	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
378	            throw new InvalidPostcodeException(
379	                "postcode " + postcode + " is not valid for the city's region " + region.name());
380	        }
381	    }
382	
383	    /**
384	     * Rejects creating an owner whose whole derived {@code identityKey} (see
385	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
386	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
387	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
388	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
389	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}).
390	     *
391	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
392	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
393	     */
394	    private void requireUniqueIdentity(Owner owner) {
395	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
396	        boolean inUse = this.clinicService.findAllOwners().stream()
397	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
398	        if (inUse) {
399	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
400	        }
401	    }
402	
403	    /**
404	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
405	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
406	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
407	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
408	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
409	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
410	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
411	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
412	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
413	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
414	     *
415	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
416	     * @param ownerFieldsDto the incoming owner payload
417	     */
418	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
419	        owner.setPossibleDuplicate(false);
420	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
421	            return;
422	        }
423	        String postcode = owner.getPostcode();
424	        if (postcode == null || postcode.isBlank()) {
425	            return;
426	        }
427	        String lastName = owner.getLastName();
428	        String telephone = owner.getTelephone();
429	        for (Owner existing : this.clinicService.findAllOwners()) {
430	            if (lastName.equalsIgnoreCase(existing.getLastName())
431	                && postcode.equals(existing.getPostcode())
432	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
433	                owner.setPossibleDuplicate(true);
434	                owner.setPossibleDuplicateOf(existing.getId());
435	                return;
436	            }
437	        }
438	    }
439	
440	    /**
441	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
442	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
