444	     * @param city the city of the owner being created
445	     * @throws OwnerCityFullException if the city already contains 50 or more owners
446	     */
447	    private void requireCityHasCapacity(String city) {
448	        long cityOwners = this.clinicService.findAllOwners().stream()
449	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
450	            .count();
451	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
452	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
453	        }
