456	    /**
457	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
458	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
459	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
460	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
461	     * such owners never match one another as a household.
462	     *
463	     * @param owner the newly mapped owner about to be saved
464	     */
465	    private void assignHouseholdId(Owner owner) {
466	        String postcode = owner.getPostcode();
467	        if (postcode == null || postcode.isBlank()) {
468	            owner.setHouseholdId(null);
469	            return;
470	        }
471	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
472	    }
