474	    /**
475	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
476	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
477	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
478	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
479	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
480	     * without a postcode) can never be a household duplicate.
481	     *
482	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
483	     * @param ownerFieldsDto the incoming owner payload
484	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
485	     *                                 declare {@code sharesHousehold}
486	     */
487	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
488	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
489	            return;
490	        }
491	        String householdId = owner.getHouseholdId();
492	        if (householdId == null) {
493	            return;
494	        }
495	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
496	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
497	        if (sharedByExisting) {
498	            throw new DuplicateOwnerException("an owner in the same household already exists");
499	        }
500	    }
