502	    /**
503	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
504	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
505	     * household is counted as a household of one.
506	     *
507	     * @param owner the owner whose household size should be resolved
508	     */
509	    private void populateHouseholdMemberCount(Owner owner) {
510	        String householdId = owner.getHouseholdId();
