293	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
294	    @ResponseBody
295	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
296	        logger.debug("Daily owner creation limit reached at {} {}: {}",
297	            request.getMethod(),
298	            request.getRequestURI(),
299	            e.getMessage());
300	        return errorResponse(e, HttpStatus.TOO_MANY_REQUESTS, request, e.getMessage(), List.of());
301	    }
302	
303	    /**
304	     * Builds the response body shared by the handlers that report a single business-rule violation: a
305	     * {@link ProblemDetail} for the given status carrying {@code detail} as its detail message and the offending field
306	     * names in its {@code errors} property.
307	     *
308	     * @param e the exception being handled, used to title the {@link ProblemDetail}
309	     * @param status the HTTP status to return
310	     * @param request {@link HttpServletRequest} object referring to the current request.
311	     * @param detail the human-readable detail message
312	     * @param errors the names of the fields the violation is reported against
313	     * @return a {@link ResponseEntity} carrying the problem detail and the given status
314	     */
315	    private ResponseEntity<ProblemDetail> errorResponse(Exception e, HttpStatus status, HttpServletRequest request,
316	                                                        String detail, List<String> errors) {
317	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
318	        problemDetail.setProperty("errors", errors);
319	        return ResponseEntity.status(status).body(problemDetail);
320	    }
321	
322	    /**
323	     * Collects the distinct field names carried by the given {@link BindingResult}, in binding order, so they can be
324	     * reported in the {@code errors} array of a validation error response.
325	     *
326	     * @param bindingResult the binding result carrying the field errors
327	     * @return the names of the rejected fields, without duplicates
328	     */
329	    private List<String> rejectedFieldNames(BindingResult bindingResult) {
330	        return bindingResult.getFieldErrors().stream()
331	            .map(FieldError::getField)
332	            .distinct()
333	            .toList();
334	    }
335	
336	    /**
337	     * Maps every field error in the given {@link BindingResult} to a {@link ValidationMessageDto} describing the
338	     * rejected field, its value and the reason it was rejected.
339	     *
340	     * @param bindingResult the binding result carrying the field errors
341	     * @return one {@link ValidationMessageDto} per field error, in binding order
342	     */
343	    private List<ValidationMessageDto> schemaValidationErrors(BindingResult bindingResult) {
344	        return bindingResult.getFieldErrors().stream()
345	            .map(this::toValidationMessage)
346	            .toList();
347	    }
348	
349	    /**
350	     * Builds a {@link ValidationMessageDto} for a single {@link FieldError}, carrying the field name, rejected value
351	     * and default message both as a human-readable message and as individual properties.
352	     *
353	     * @param fieldError the rejected field
354	     * @return the validation message describing it
355	     */
356	    private ValidationMessageDto toValidationMessage(FieldError fieldError) {
357	        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
358	        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
359	        String message = "Field '%s' %s (rejected value: %s)".formatted(
360	            fieldError.getField(),
361	            defaultMessage,
362	            rejectedValue);
363	        return new ValidationMessageDto(message)
364	            .putAdditionalProperty("field", fieldError.getField())
365	            .putAdditionalProperty("rejectedValue", rejectedValue)
366	            .putAdditionalProperty("defaultMessage", defaultMessage);
367	    }
368	
369	}
