17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Set;
20	
21	import org.springframework.samples.petclinic.rest.advice.DisposableEmailException;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Turns owner emails into the single canonical form that gets stored, returned and compared, so the REST controllers do
26	 * not have to carry the email rules themselves.
27	 *
28	 * <p>A syntactically valid address is already enforced by Bean Validation on the request payload, so normalization only
29	 * canonicalizes the value by lower-casing it. So {@code "Owner@Example.TEST"} becomes {@code "owner@example.test"}.
30	 *
31	 * <p>Normalization also rejects any address whose domain is on the disposable-domain blocklist
32	 * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), since such throwaway addresses are not
33	 * acceptable owner contacts. The comparison is case-insensitive because the value is canonicalized (lower-cased) first.
34	 *
35	 * <p>Unlike the address and telephone, an email is optional: a missing (blank or {@code null}) value is left untouched,
36	 * so callers can uniformly treat a blank result as a missing email. The same canonical form is used both for the value
37	 * that is stored and returned and for every email comparison (such as duplicate detection across existing owners), so
38	 * incidental case differences never affect the outcome.
39	 */
40	@Component
41	public class EmailNormalizer {
42	
43	    /** Domains of throwaway email providers that an owner's email may not use. */
44	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
45	        "mailinator.com", "tempmail.com", "guerrillamail.com");
46	
47	    /**
48	     * Normalizes an owner email into its canonical stored form by lower-casing it. A missing (blank or {@code null})
49	     * email is returned untouched, since the field is optional. The normalized value is what gets stored and returned as
50	     * {@code email}, and the same form is used when comparing an owner's email against those of existing owners. An
51	     * email whose domain is on the disposable-domain blocklist is rejected.
52	     *
53	     * @param email the raw email value from the request, may be {@code null}
54	     * @return the lower-cased email, or the original value when none was supplied
55	     * @throws DisposableEmailException if the email's domain is on the disposable-domain blocklist
56	     */
57	    public String normalize(String email) {
58	        if (email == null || email.isBlank()) {
59	            return email;
60	        }
61	        String normalized = email.toLowerCase();
62	        rejectDisposableDomain(normalized);
63	        return normalized;
64	    }
65	
66	    /**
67	     * Rejects a normalized email whose domain (the part after the final {@code '@'}) is on the disposable-domain
68	     * blocklist. An address without a domain part is left to Bean Validation's syntactic check and passes here.
69	     *
70	     * @param normalized the lower-cased email
71	     * @throws DisposableEmailException if the domain is on the disposable-domain blocklist
72	     */
73	    private void rejectDisposableDomain(String normalized) {
74	        int at = normalized.lastIndexOf('@');
75	        if (at < 0) {
76	            return;
77	        }
78	        String domain = normalized.substring(at + 1);
79	        if (DISPOSABLE_DOMAINS.contains(domain)) {
80	            throw new DisposableEmailException(
81	                "email domain " + domain + " is on the disposable-domain blocklist");
82	        }
83	    }
84	}
